<script setup lang="ts">
import {localize} from './localization';

import {inject,onMounted,onUnmounted,ref,watch} from 'vue';
import ToolIcon from './ToolIcon.vue';
import PreviewPiecePicker from './PreviewPiecePicker.vue';
import {usePatternContext} from './modules/patternEditorContext';
const advanced=inject('advancedMode',ref(false));
const {measureMm,language,t,stage,selectedId,choiceIds,draftClosed,tool,draft,preview,svg,view,viewportSize,zoomPercent,scaleRuler,previewBounds,snap,holeTarget,paper,measurement,mappedPoint,candidateMode,shownMarkings,shownPieces,previewPaper,paperSize,fmt,label,cutPath,cachedPiecePath,cachedAnchor,poly,allNodes,cancel,changeTool,changePreviewTool,rectangle,circle,finish,down,move,up,zoom,zoomBy,setZoomPercent,fit,focusSelection,transform}=usePatternContext();
let resizeObserver:ResizeObserver|undefined;
onMounted(()=>{if(svg.value){resizeObserver=new ResizeObserver(()=>{if(svg.value)viewportSize.value={width:svg.value.clientWidth||800,height:svg.value.clientHeight||600};});resizeObserver.observe(svg.value);}});
onUnmounted(()=>resizeObserver?.disconnect());
watch([advanced,tool],([value,current])=>{if(!value&&current==='node'){cancel();tool.value='select';}});
</script>
<template><section class="pattern-editor" aria-label="2D cut pattern preview"><div class="editor-top"><strong>2D <span> / {{language==='zh'?(candidateMode?'裁片候选预览':'单片 / 裁版预览'):'Cut pattern preview'}}</span></strong><div class="spacer"></div><PreviewPiecePicker v-if="stage==='cutting'"/><label class="canvas-zoom"><input type="number" min="10" max="3200" step="10" :value="Math.round(zoomPercent)" :aria-label="language==='zh'?'预览缩放百分比':localize('Preview zoom percent')" @change="setZoomPercent(Number(($event.target as HTMLInputElement).value))">%</label><span v-if="previewBounds" class="physical-size" aria-label="Actual piece dimensions">{{fmt(previewBounds.widthMm)}} × {{fmt(previewBounds.heightMm)}} mm</span><label v-if="advanced&&stage==='pattern'"><input v-model="snap" type="checkbox">{{t.snap}} 5 mm</label></div><div v-if="stage==='pattern'" class="paper-preview-control"><label>{{language==='zh'?'打印纸张背景':localize('Paper background')}}<select v-model="previewPaper" aria-label="裁片纸张背景"><option>A4</option><option>A3</option><option v-if="previewPaper==='Custom'" disabled>Custom</option></select></label><span>{{paperSize[0]}} × {{paperSize[1]}} mm ({{paperSize[0]/10}} × {{paperSize[1]/10}} cm) · {{language==='zh'?'背景为纸张大小；实际分区见拼接预览':localize('Paper-size background; see page preview for exact tiling')}}</span></div><div class="drawing-area"><nav class="tool-rail pattern-icon-rail" :aria-label="language==='zh'?'版型工作区工具':localize('Pattern workarea tools')"><button :title="t.select" :aria-label="t.select" :aria-pressed="tool==='select'" :class="{active:tool==='select'}" @click="changePreviewTool('select')"><ToolIcon name="select"/></button><button :title="language==='zh'?'手形平移':localize('Pan')" :aria-label="language==='zh'?'手形平移':localize('Pan')" :aria-pressed="tool==='pan'" :class="{active:tool==='pan'}" @click="changePreviewTool('pan')"><ToolIcon name="pan"/></button><template v-if="stage==='pattern'"><button v-if="advanced" :title="t.node" :aria-label="t.node" :aria-pressed="tool==='node'" :class="{active:tool==='node'}" @click="changeTool('node')"><ToolIcon name="node"/></button><button :title="t.measure" :aria-label="t.measure" :aria-pressed="tool==='measure'" :class="{active:tool==='measure'}" @click="changeTool('measure')"><ToolIcon name="measure"/></button><button :disabled="!selectedId" :title="t.rotate" :aria-label="t.rotate" @click="transform('rotate')"><ToolIcon name="rotate"/></button></template><button :title="language==='zh'?'放大':localize('Zoom in')" :aria-label="language==='zh'?'放大':localize('Zoom in')" @click="zoomBy(1.25)"><ToolIcon name="zoomIn"/></button><button :title="language==='zh'?'缩小':localize('Zoom out')" :aria-label="language==='zh'?'缩小':localize('Zoom out')" @click="zoomBy(1/1.25)"><ToolIcon name="zoomOut"/></button><button :title="t.fit" :aria-label="t.fit" @click="fit"><ToolIcon name="fit"/></button><button :disabled="!selectedId&&!choiceIds.length" :title="language==='zh'?'聚焦裁片':localize('Focus pattern')" :aria-label="language==='zh'?'聚焦裁片':localize('Focus pattern')" @click="focusSelection"><ToolIcon name="eye"/></button></nav>
    <svg ref="svg" class="canvas" :viewBox="`${view.x} ${view.y} ${view.w} ${view.h}`" @pointerdown="down($event)" @pointermove="move" @pointerup="up" @pointercancel="cancel" @wheel="zoom" @contextmenu.prevent>
     <defs><pattern id="grid" width="10" height="10" patternUnits="userSpaceOnUse"><path d="M 10 0 L 0 0 0 10" fill="none" stroke="var(--border)" stroke-width="0.25"/></pattern><pattern id="major" width="50" height="50" patternUnits="userSpaceOnUse"><rect width="50" height="50" fill="url(#grid)"/><path d="M 50 0 L 0 0 0 50" fill="none" stroke="#a7bfd3" stroke-width="0.4"/></pattern><pattern id="paper-grid" :width="paperSize[0]" :height="paperSize[1]" patternUnits="userSpaceOnUse"><rect :width="paperSize[0]" :height="paperSize[1]" fill="var(--studio-white)"/><path :d="`M ${paperSize[0]} 0 L 0 0 0 ${paperSize[1]}`" fill="none" stroke="#829bb3" :stroke-width="view.w/600"/><rect :x="paper.marginMm" :y="paper.marginMm" :width="paperSize[0]-2*paper.marginMm" :height="paperSize[1]-2*paper.marginMm" fill="none" stroke="var(--border)" stroke-dasharray="3 2" :stroke-width="view.w/1200"/><text x="8" y="12" fill="var(--text-muted)" font-size="5">{{previewPaper}} · {{paperSize[0]}} × {{paperSize[1]}} mm</text></pattern></defs>
     <rect :x="view.x" :y="view.y" :width="view.w" :height="view.h" :fill="stage==='pattern'?'url(#paper-grid)':'url(#major)'"/>
     <line :x1="view.x" y1="0" :x2="view.x+view.w" y2="0" stroke="#829bb3" stroke-width=".4"/><line x1="0" :y1="view.y" x2="0" :y2="view.y+view.h" stroke="#829bb3" stroke-width=".4"/>
     <g v-for="p in shownPieces" :key="p.id" v-memo="[p,selectedId,choiceIds,stage,tool,view.w,shownMarkings,preview?.id]" @pointerdown.stop="down($event,p)">
      <path v-if="!preview||preview.id!==p.id" :d="cutPath(p.id)" fill-rule="evenodd" :fill="p.color" fill-opacity=".8" stroke="var(--studio-teal)" stroke-width=".6"/>
      <path :d="cachedPiecePath(p)" fill-rule="evenodd" :fill="p.closed?p.color:'none'" :fill-opacity="p.id===selectedId||choiceIds.includes(p.id)?.24:.12" :stroke="p.id===selectedId||choiceIds.includes(p.id)?'var(--studio-teal)':'var(--studio-navy)'" :stroke-width="p.id===selectedId||choiceIds.includes(p.id)?1:.5" stroke-dasharray="3 1.5"/>
      <template v-for="m in shownMarkings" :key="m.id"><path v-for="path in m.paths.filter(path=>path.pieceId===p.id)" :key="path.pieceId" :d="path.rings.map(r=>r.map((n,i)=>(i?'L':'M')+n.xMm+','+(-n.yMm)).join(' ')+' Z').join(' ')" :fill="m.color" fill-opacity=".95" fill-rule="evenodd" stroke="var(--warning)" stroke-width=".25"><title>{{m.name}}</title></path></template>
      <text :x="cachedAnchor(p).xMm" :y="-cachedAnchor(p).yMm" text-anchor="middle" font-size="5" fill="var(--ink)">{{p.name}}</text>
      <g class="piece-direction" :transform="`translate(${cachedAnchor(p).xMm},${-cachedAnchor(p).yMm}) rotate(${90-(p.furRad||0)*180/Math.PI}) scale(${Math.min(1,cachedAnchor(p).clearanceMm/15)})`" pointer-events="none"><path d="M 0 10 L 0 -8 M -3 -3 L 0 -8 L 3 -3" fill="none" stroke="var(--ink)" stroke-width="1"/></g><text v-for="l in p.labels??[]" :key="l.id" :x="l.xMm" :y="-l.yMm" font-size="4" fill="var(--ink)">{{l.text}}</text>
      <template v-if="stage==='pattern'&&p.id===selectedId&&tool==='node'"><g v-for="c in p.curves??[]" :key="c.id"><circle :cx="c.c1.xMm" :cy="-c.c1.yMm" r="1.5" fill="var(--warning)"/><circle :cx="c.c2.xMm" :cy="-c.c2.yMm" r="1.5" fill="var(--warning)"/></g></template>
      <g v-if="stage==='pattern'&&p.id===selectedId&&tool==='node'"><circle v-for="n in allNodes(p)" :key="n.id" :cx="n.xMm" :cy="-n.yMm" :r="view.w/180" fill="var(--studio-white)" stroke="var(--studio-teal)" :stroke-width="view.w/650" @pointerdown.stop="down($event,p,n)"/></g>
     </g>
     <circle v-if="mappedPoint?.pieceId===selectedId" :cx="mappedPoint.xMm" :cy="-mappedPoint.yMm" :r="view.w/120" fill="none" stroke="var(--warning)" :stroke-width="view.w/500"/><polyline v-if="draft.length" :points="poly(draft)" fill="var(--studio-teal)" fill-opacity=".1" stroke="var(--studio-teal)" stroke-width=".8"/>
     <circle v-for="n in draft" :key="n.id" :cx="n.xMm" :cy="-n.yMm" r="2" fill="var(--studio-teal)"/>
     <polyline v-if="measurement.length" :points="poly(measurement)" stroke="var(--warning)" stroke-width=".8"/>
     <circle v-for="n in measurement" :key="n.id" :cx="n.xMm" :cy="-n.yMm" r="2" fill="var(--warning)"/>
    </svg>
    <div v-if="!shownPieces.length&&!draft.length" class="canvas-empty"><div class="outline-shape">◇</div><h2>{{stage==='cutting'?(language==='zh'?'裁片预览':localize('Cut preview')):(language==='zh'?'从裁切库获取版型':localize('Load patterns from the cutting library'))}}</h2><p>{{stage==='cutting'?(language==='zh'?'设置裁剪线后计算展开候选，在此检查轮廓与颜色。':localize('Compute an unwrap candidate to inspect contours and colors here.')):(language==='zh'?'在右侧选择保存的裁切版本，载入后预览、微调与打印。':localize('Select a saved cut version on the right, then preview, adjust and print.'))}}</p></div>
    <div v-if="stage==='pattern'&&tool==='polygon'" class="gesture-bar">{{holeTarget?(language==='zh'?'孔洞 · ':localize('Hole · ')):!draftClosed?(language==='zh'?'开放路径 · ':localize('Open path · ')):''}}{{draft.length}} {{t.point}} <button :disabled="draft.length<(draftClosed?3:2)" @click="finish">{{t.finish}} ↵</button><button @click="cancel">{{t.cancel}} Esc</button></div>
    <div v-if="stage==='pattern'&&tool==='measure'" class="gesture-bar">{{t.distance}}: {{fmt(measureMm)}} mm</div>
    <div class="canvas-metadata"><div class="scale-ruler" :aria-label="`${fmt(scaleRuler.mm)} mm ruler`"><span :style="{width:scaleRuler.pixels+'px'}"/><b>{{fmt(scaleRuler.mm)}} mm</b></div><div class="canvas-legend"><span class="solid-line"></span>{{t.cut}}<span class="dashed-line"></span>{{t.seam}}<b>mm</b></div></div>
   </div><div class="editor-bottom">{{stage==='cutting'?(language==='zh'?'滚轮缩放 · 中键平移 · 选择裁片可聚焦查看':localize('Wheel to zoom · Middle drag to pan · Select a piece to focus')):tool==='node'?t.nodeHint:(language==='zh'?'左键选择 / 编辑 · 滚轮缩放 · 中键拖动平移':localize('Left to select / edit · Wheel zoom · Middle drag to pan'))}}</div>

   </section></template>

<style scoped>.pattern-icon-rail{height:auto;max-height:calc(100% - 78px);width:48px;gap:4px;padding:6px;overflow-y:auto;overflow-x:hidden}.pattern-icon-rail button{display:flex;align-items:center;justify-content:center;padding:7px;min-height:35px;width:34px}.canvas-zoom{display:flex;align-items:center;gap:4px;font-size:11px;margin:0}.canvas-zoom input{width:66px;font-size:11px;padding:4px}.physical-size{font-size:11px;color:var(--text-muted);white-space:nowrap}.scale-ruler{position:absolute;bottom:16px;left:62px;display:flex;flex-direction:column;align-items:flex-start;gap:4px;pointer-events:none;padding:6px 9px;background:color-mix(in srgb,var(--panel) 90%,transparent);border-radius:4px;color:var(--ink)}.scale-ruler span{height:7px;border-inline:1px solid currentColor;border-bottom:2px solid currentColor}.scale-ruler b{font-size:10px;font-weight:500}.canvas-legend{pointer-events:none}</style>

<style scoped>.canvas-metadata{position:absolute;bottom:12px;left:62px;right:12px;display:flex;align-items:flex-end;justify-content:space-between;flex-wrap:wrap;gap:8px;pointer-events:none}.canvas-metadata .scale-ruler,.canvas-metadata .canvas-legend{position:static;max-width:100%}.canvas-metadata .canvas-legend{flex-wrap:wrap}.canvas-metadata .scale-ruler span{max-width:100%}.canvas-empty{left:calc(50% + 24px);width:calc(100% - 68px);max-width:280px}.canvas-empty p{overflow-wrap:anywhere}</style>
